// Byte containers for casting to u8[] (tests/npm/js_bytes.tov).
exports.uint8 = () => new Uint8Array([1, 2, 255]);
exports.clamped = () => new Uint8ClampedArray([7, 8]);
exports.arrayBuffer = () => new Uint8Array([10, 20, 30, 40]).buffer;
// a view starting at byte 2 of its buffer
exports.view = () => new Uint8Array([0, 1, 2, 3, 4, 5]).subarray(2, 5);
exports.empty = () => new Uint8Array(0);
exports.emptyBuffer = () => new ArrayBuffer(0);
// a plain array of numbers still converts element by element
exports.numbers = () => [4, 5, 6];
